DECK = [878, 878, 878, 878, 879, 879, 879, 879, 311, 311, 311, 311, 304, 304, 1115, 1115, 1115, 1115, 1152, 1152, 1152, 1152, 1111, 1122, 1122, 1097, 1097, 1123, 1123, 1171, 1171, 1171, 1171, 1227, 1227, 1227, 1227, 1225, 1225, 1225, 1225, 1182, 1182, 1197, 1197, 1184, 1255, 1255, 1255, 1255, 19, 19, 19, 19, 11, 11, 11, 11, 1086, 1086]
"""Hop tempo pilot. Uses only the supplied public observation and legal options.

The build script prepends the official card metadata and the fixed 60-card deck.
No simulator, file system, networking, NumPy, or other package is needed at play.
"""
from collections import Counter
from copy import deepcopy

MEMORY = {'turn': -1, 'revenge_for': -100, 'damage_flags': {}, 'enemy_attack': None, 'dodge': None}

def cid(x):
    return x.get('id', 0) if isinstance(x, dict) else x if isinstance(x, int) else 0

def card(x):
    return CARDS.get(cid(x), {})

def name(x):
    return card(x).get('name', '')

def units(p):
    e=(p or {}).get('energies') or []
    return list(e) if isinstance(e,list) else [int(k) for k,v in e.items() for _ in range(v)]

def prizes(p):
    seq=p.get('prize') or []
    # Native CABT returns one null for each hidden, remaining prize and
    # removes taken entries. Visible-card variants use nulls for taken slots.
    return sum(x is not None for x in seq) if any(x is not None for x in seq) else len(seq)

def field(p):
    return [x for x in (p.get('active') or [])+(p.get('bench') or []) if x]

def active(p):
    return next(iter(p.get('active') or []),None)

def tool(p, i, st=None):
    if st and cid(next(iter(st['cur'].get('stadium') or []),None))==1246:
        return False
    return any(cid(t)==i for t in (p or {}).get('tools',[]))

def hop(p):
    return name(p).replace('’', "'").startswith("Hop's")

def state(obs):
    cur=obs['current']; mi=cur['yourIndex']; me=cur['players'][mi]; opp=cur['players'][1-mi]
    turn=cur['turn']
    if turn < MEMORY['turn']:
        MEMORY.update(turn=-1,revenge_for=-100,damage_flags={},enemy_attack=None,dodge=None)
    logs=obs.get('logs') or []
    # Infer log turn numbers backwards: logs can span both players' turns.
    # A revenge trigger requires attack DAMAGE. Alakazam places counters,
    # which do not trigger Horrifying Revenge even when they cause a KO.
    logturn=turn
    timed=[]
    for log in reversed(logs):
        timed.append((logturn,log))
        if log.get('type')==2:logturn-=1
    attacking=False
    for lt,log in reversed(timed):
        if log.get('type')==15:
            attacking=log.get('playerIndex')==1-mi
            if attacking:MEMORY['enemy_attack']=(lt,log.get('attackId'),log.get('serial'))
        if log.get('type')==22 and log.get('playerIndex')==1-mi and log.get('head'):
            last=MEMORY.get('enemy_attack')
            if last and last[:2]==(lt,1266):
                MEMORY['dodge']=(lt+1,last[2])
        if log.get('type')==8 and log.get('playerIndex')==1-mi:
            MEMORY['dodge']=None
        if log.get('type')==16 and log.get('playerIndex')==mi:
            MEMORY['damage_flags'][log.get('serial')]=(lt,not log.get('putDamageCounter',False))
        if (log.get('type')==6 and log.get('playerIndex')==mi
            and log.get('fromArea') in (4,5) and log.get('toArea')==3
            and hop(log.get('cardId'))
            and MEMORY['damage_flags'].get(log.get('serial'))==(lt,True)
            and (attacking or (MEMORY.get('enemy_attack') or (-100,None))[0]==lt)):
            MEMORY['revenge_for']=lt+1
    MEMORY['turn']=turn
    revenge=MEMORY['revenge_for']==turn
    st={'obs':obs,'cur':cur,'mi':mi,'me':me,'opp':opp,'a':active(me),'oa':active(opp),
        'board':field(me),'enemy':field(opp),'hand':me.get('hand') or [],'revenge':revenge}
    st['counts']=Counter(cid(x) for x in st['board'])
    st['hc']=Counter(cid(x) for x in st['hand'])
    st['stadium']=cid(next(iter(cur.get('stadium') or []),None))
    return st

def resolve(st,o):
    area=o.get('area'); idx=o.get('index',0); pi=o.get('playerIndex')
    p=st['cur']['players'][st['mi'] if pi is None else pi]
    zones={1:st['obs']['select'].get('deck'),2:p.get('hand'),3:p.get('discard'),
           4:p.get('active'),5:p.get('bench'),6:p.get('prize'),7:st['cur'].get('stadium'),
           12:st['cur'].get('looking')}
    seq=zones.get(area) or []
    obj=seq[idx] if isinstance(idx,int) and 0<=idx<len(seq) else None
    if o.get('type') in (4,5,6) and obj:
        key='tools' if o['type']==4 else 'energyCards'
        j=o.get('toolIndex') if o['type']==4 else o.get('energyIndex')
        seq=obj.get(key) or []
        obj=seq[j] if isinstance(j,int) and 0<=j<len(seq) else None
    return obj

def target(st,o):
    area=o.get('inPlayArea'); i=o.get('inPlayIndex',0)
    seq=st['me'].get('active' if area==4 else 'bench') or []
    return seq[i] if isinstance(i,int) and 0<=i<len(seq) else None

def can_pay(p, cost, st):
    c=list(cost)
    if tool(p,1171,st) and hop(p) and 0 in c:
        c.remove(0)
    if card(p).get('tera') and st['stadium']==1266:
        c.append(0)
    e=units(p)
    for t in sorted(c, key=lambda x:x==0):
        if t and t in e:e.remove(t)
        elif 10 in e:e.remove(10)
        elif t==0 and e:e.pop()
        else:return False
    return True

def damage(st,p,q,aid,opponent=False):
    if not p or not q:return 0
    at=next((a for a in card(p).get('attacks',[]) if a[0]==aid),None)
    if not at:return 0
    d=at[1]; board=st['enemy'] if opponent else st['board']
    if not opponent and MEMORY.get('dodge')==(st['cur']['turn'],q.get('serial')):
        return 0
    if aid==1072:
        d=20*(st['opp'].get('handCount',0) if opponent else len(st['hand']))
        # Powerful Hand places counters: no Weakness, Resistance, damage
        # bonuses or ex immunity apply, and Mist Energy prevents the effect.
        return 0 if any(cid(e)==11 for e in q.get('energyCards',[])) else d
    elif aid==1267:
        d=130 if (opponent or st['revenge']) else 30
    elif aid==433:
        # Fickle Spitting works ONLY with exactly 3 or 4 opposing prizes.
        defending_player=st['me'] if opponent else st['opp']
        if prizes(defending_player) not in (3,4):return 0
    elif aid==363:
        d=20+20*sum(units(x).count(4) for x in board)
    elif aid==1042:
        pl=st['opp'] if opponent else st['me']
        d=20*sum(cid(x)==3 for x in pl.get('discard',[]))
    elif aid==1046:
        pl=st['opp'] if opponent else st['me']
        # Expected value from the public deck composition, never deck order.
        used=sum(cid(x)==3 for x in pl.get('discard',[]))+sum(sum(cid(e)==3 for e in x.get('energyCards',[])) for x in board)
        d=600*max(0,31-used)/max(1,pl.get('deckCount',1)+pl.get('handCount',0)+prizes(pl))
    if hop(p):
        d+=30*any(cid(x)==304 for x in board)
        d+=30*(st['stadium']==1255)
        d+=30*tool(p,1171,st)
    if tool(p,1158,st) and (card(q).get('ex') or card(q).get('mega')):d+=50
    # Damage prevention applies to damage, not damage counters.
    text=card(q).get('skills','').lower()
    if cid(q)==345 and (card(p).get('ex') or card(p).get('mega')):return 0
    if 'prevent all damage' in text:
        if 'basic pok' in text and card(p).get('basic'):return 0
        if 'have an ability' in text and card(p).get('skills'):return 0
        if 'special energy' in text and any(card(x).get('kind')==6 for x in p.get('energyCards') or []):return 0
    typ=card(p).get('energy',0)
    if card(q).get('weakness')==typ and typ:d*=2
    if card(q).get('resistance')==typ and typ:d=max(0,d-30)
    last=MEMORY.get('enemy_attack')
    if not opponent and last and last==(st['cur']['turn']-1,1047,q.get('serial')):
        d=max(0,d-30)
    return max(0,d)

def attacks(st,p,q,opponent=False):
    return [(a[0],damage(st,p,q,a[0],opponent)) for a in card(p).get('attacks',[]) if can_pay(p,a[2],st)]

def best(st,p=None,q=None,opponent=False):
    p=p or st['a'];q=q or st['oa']
    return max((d for _,d in attacks(st,p,q,opponent)),default=0)

def prize_value(p):
    return 3 if card(p).get('mega') else 2 if card(p).get('ex') else 1

def attack_value(st,p,q,d):
    if not p or not q:return 0
    hp=q.get('hp',999)
    if d>=hp:
        if prizes(st['me'])<=prize_value(q) or len(st['enemy'])==1:
            return 100000
        return 1000+350*prize_value(q)
    return 150+min(d,hp)*1.4 if d else 10

def ready_value(st,p):
    if not p:return -10000
    d=best(st,p)
    val=attack_value(st,p,st['oa'],d)
    if cid(p)==878 and not p.get('appearThisTurn') and st['hc'][879]:val+=300
    if hop(p) and not p.get('tools') and st['hc'][1171]:val+=250
    if cid(p)==304:val-=300
    if st['oa'] and best(st,st['oa'],p,True)>=p.get('hp',1):val-=70*prize_value(p)
    return val+min(p.get('hp',0),150)*.3

def value(st,c,extra=None):
    """Marginal value of obtaining a card, relative to board and hand needs."""
    c=cid(c);n=st['counts'];h=st['hc']; extra=extra or Counter(); copies=n[c]+h[c]+extra[c]
    if c==304:return 1100 if not copies else 0
    if c==311:
        usable=prizes(st['opp']) in (3,4)
        return (1000 if usable else 250)/(1+copies*2)
    if c==878:return 1100/(1+copies*2) if n[878]+n[879]<3 else 40
    if c==879:return 1250 if n[878]>h[879]+extra[c] else 100/(1+copies)
    if c==1171:
        untooled=sum(hop(p) and not p.get('tools') for p in st['board'] if cid(p)!=304)
        return 1200 if untooled>h[c]+extra[c] else 150/(1+copies)
    if c==1255:return 950 if st['stadium']!=1255 and not h[c]+extra[c] else 40
    if c==19:return 1150 if not st['cur'].get('energyAttached') and not h[c]+extra[c] else 250/(1+h[c]+extra[c])
    if card(c).get('kind') in (5,6):
        return 650 if not st['cur'].get('energyAttached') and not sum(h[i] for i in h if card(i).get('kind') in (5,6)) else 100
    if c==1115:return 1000 if len(st['board'])<4 else 30
    if c==1086:return 950 if n[878]+n[879]<2 else 50
    if c==1152:return 950 if n[878] and not h[879] else 650 if len(st['board'])<4 else 250
    if c==1111:return 1050 if any(not p.get('tools') and hop(p) and cid(p)!=304 for p in st['board']) else 30
    if c==1225:return 1100 if n[878] and not h[879] else 700 if not st['cur'].get('energyAttached') else 200
    if c==1227:return 1000 if len(st['hand'])<5 else 250
    if c==1197:return 850 if st['opp'].get('handCount',0)>=8 else 100
    if c in (1097,1184):return 800 if any(cid(p) in (879,311) for p in st['me'].get('discard',[])) else 20
    if c==1182:return 600 if any(best(st,q=p)>=p.get('hp',999) for p in st['opp'].get('bench',[])) else 150
    if c==1123:return 900 if st['a'] and best(st)==0 and any(best(st,p)>0 for p in st['me'].get('bench',[])) else 100
    if c==1219:return 700
    if c==1134:return 500 if not st['cur'].get('supporterPlayed') else 50
    if c==1122:return 650 if not st['cur'].get('supporterPlayed') else 50
    if c==1092:return 600
    if c==1080:return 850
    return 150 if card(c).get('kind')==3 else 50

def play_score(st,c):
    n=st['counts'];h=st['hc']; p=st['a']; q=st['oa']; d=best(st)
    if card(c).get('basic'):
        if c==304:return 2100 if not n[c] else -100
        if c==878:return 1700 if n[878]+n[879]<2 else 500 if n[878]+n[879]<3 else -50
        if c==311:return 1800 if not n[c] and prizes(st['opp']) in (3,4) else 250 if not n[c] else -50
        return 600
    if c==1255:
        return 2200 if st['stadium']!=c else -100
    if c==1115:return 1900 if len(st['board'])<4 else -20
    if c==1086:return 1900 if n[878]+n[879]<2 else -20
    if c==1111:return 2000 if any(hop(x) and cid(x)!=304 and not x.get('tools') for x in st['board']) and not h[1171] else -10
    if c==1152:
        return 1900 if n[878] and not h[879] else 1500 if len(st['board'])<4 else -10
    if c==1225:
        return 1950 if n[878] and not h[879] else 1450 if not st['cur'].get('energyAttached') and not h[19] else 100
    if c==1227:
        # Play useful pieces before shuffling. Search supporters compete with
        # draw supporters by actual need; a 12-card hand is not an improvement.
        return 1700 if len(st['hand'])<=4 else 1000 if len(st['hand'])<=6 else -10
    if c==1182:
        vals=[attack_value(st,p,x,best(st,p,x)) for x in st['opp'].get('bench',[])]
        gain=max(vals,default=0)-attack_value(st,p,q,d)
        return 1800+gain if gain>300 else -50
    if c==1197:
        hc=st['opp'].get('handCount',0)
        if any(cid(x)==743 for x in st['enemy']):
            # Do not take our only supporter action before developing an
            # attacker. Disruption is useful when it saves an assembled body.
            return 1800 if hc>=8 and (d>0 or len(st['hand'])>=7) else 300
        return 900 if hc>=9 else -10
    if c==1219:
        need=max(value(st,i) for i in (1115,1152,1171,1255,1111,1123))
        return 1500 if need>=950 else -10
    if c==1134:return 1400 if not st['cur'].get('supporterPlayed') and not any(card(x).get('kind')==3 for x in st['hand']) else -20
    if c==1122:return 1500 if not st['cur'].get('supporterPlayed') and not any(card(x).get('kind')==3 for x in st['hand']) else -10
    if c in (1097,1184):
        needs=[value(st,x) for x in st['me'].get('discard',[]) if card(x).get('kind')==0]
        return 1600 if max(needs,default=0)>=900 else -10
    if c==1092:return 1350 if len(st['hand'])>=7 and (not h[1171] or st['stadium']!=1255) else -10
    if c==1123:return 2000 if any(ready_value(st,x)>ready_value(st,p)+250 for x in st['me'].get('bench',[])) else -50
    if c==1080:return 2000 if st['opp'].get('handCount',0)>=7 else 1600 if len(st['hand'])<5 else 0
    return 100

def main_score(st,o):
    t=o.get('type');p=st['a'];q=st['oa']; hand=st['hand']
    if t==14:return -100
    if t==13:
        d=damage(st,p,q,o.get('attackId'))
        return attack_value(st,p,q,d)
    if t==7:
        i=o.get('index',-1)
        return play_score(st,cid(hand[i]))+400 if 0<=i<len(hand) else -1000
    if t==9:
        z=target(st,o)
        return 2300 if z==p else 1800
    if t==8:
        z=target(st,o);i=o.get('index',-1)
        if z is None or i<0 or i>=len(hand):return -1000
        c=cid(hand[i]);before=best(st,z); zz=deepcopy(z)
        if card(c).get('kind')==2:
            zz.setdefault('tools',[]).append(hand[i])
            after=best(st,zz)
            if c==1171:
                if cid(z)==304:return 50
                return 2400 if z==p and after>before else 2000 if cid(z) in (311,879) else 1800
            return 400
        if cid(z)==304:return 50
        counters=any(cid(x) in (743,121) for x in st['enemy'])
        protected=any(cid(e)==11 for e in z.get('energyCards',[]))
        if c==11 and counters and not protected:
            return 2600 if z==p else 1850 if cid(z)==879 else 1700
        if len(units(z))>=3:return -10
        zz['energies']=units(z)+[card(c).get('energy',0)]
        after=best(st,zz)
        if len(units(z))>=1 and after<=before:
            return -10
        v=2100 if z==p and after>before else 1650 if cid(z) in (878,879) else 1500
        if c==19 and len(st['board'])<4:v+=150
        if tool(z,1171,st) and before>0:v-=1000
        return v
    if t==12:
        a=ready_value(st,p); b=max((ready_value(st,x) for x in st['me'].get('bench',[])),default=-9999)
        return 1700+b-a if b>a+300 else -200
    if t==10:return 300
    if t==11:return -500
    return 0

def choice_score(st,sel,o,extra):
    ctx=sel.get('context'); t=sel.get('type'); obj=resolve(st,o); c=cid(obj)
    own=o.get('playerIndex',st['mi'])
    if own is None:own=st['mi']
    if t==9:
        if ctx==41:return 10 if o.get('type')==2 else 0 # Hop attacks on turn 1 going second.
        return 10 if o.get('type')==1 else 0
    if t==8:
        num=o.get('number',0)
        if ctx==38:
            safe=max(0,st['me'].get('deckCount',0)-3)
            return num if num<=safe else -num
        if ctx==39:
            hp=(sel.get('contextCard') or {}).get('hp',0)
            return num if not hp or num<=max(1,(hp+9)//10) else -num
        return num
    if t==6:return damage(st,st['a'],st['oa'],o.get('attackId'))
    if ctx in (1,2,5,6):
        if ctx==1:
            return {311:100,878:1000,304:300}.get(c,200)
        return value(st,c,extra)
    if ctx in (3,4):
        if own!=st['mi']:
            d=best(st,q=obj)
            return attack_value(st,st['a'],obj,d)-len(units(obj))*5
        return ready_value(st,obj)
    if ctx in (8,9,10,11,26,27,29,30,32):
        if own!=st['mi']:
            return 100+len(units(obj))*20+prize_value(obj)*20
        if t==4:
            return 100 if o.get('energyIndex',0)>=1 else -50
        return -value(st,c,extra)-40*extra[c]
    if ctx==22:
        if not obj:return 0
        if sel.get('effect') and cid(sel['effect'])==1171:
            return (1000 if obj==st['a'] else 700) if cid(obj) in (311,879,878) else 0
        return 1000-len(units(obj))*200 if cid(obj)!=304 else 0
    if ctx in (13,14,15):
        if not obj:return 0
        if own==st['mi']:return -prize_value(obj)*100+obj.get('hp',0)
        hp=obj.get('hp',999)
        return 1000*prize_value(obj) if hp<=sel.get('remainDamageCounter',1)*10 else 500-hp
    if ctx in (16,17):return obj.get('maxHp',0)-obj.get('hp',0) if obj else 0
    if ctx==25 and own!=st['mi']:
        return prize_value(obj)*1000-obj.get('hp',999) if obj else 0
    return value(st,c,extra)

def agent(obs_dict):
    sel=(obs_dict or {}).get('select')
    # A missing select means there is nothing to choose. Returning the deck list
    # here (as the original did) hands the platform 60 out-of-range indices,
    # which is an instant loss. Return an empty selection instead.
    if sel is None:return []
    options=sel.get('option') or []
    lo=sel.get('minCount',0);hi=min(sel.get('maxCount',len(options)),len(options))
    if not options or hi==0:return []
    st=state(obs_dict)
    if sel.get('type')==0:
        scored=[(main_score(st,o),i) for i,o in enumerate(options)]
        return sorted([max(scored,key=lambda p:(p[0],-p[1]))[1]])
    selected=[]; extra=Counter(); available=set(range(len(options)))
    while available and len(selected)<hi:
        ranked=[(choice_score(st,sel,options[i],extra),i) for i in available]
        score,i=max(ranked,key=lambda p:(p[0],-p[1]))
        if len(selected)>=lo:
            if sel.get('type') in (8,9,6,5,10):break
            if sel.get('context') in (2,5,6,7,21) and score<=100:break
            if sel.get('context') not in (2,5,6,7,21):break
        selected.append(i);available.remove(i);extra[cid(resolve(st,options[i]))]+=1
    return sorted(selected)


# --- hard legality guard (v3) -------------------------------------------------
_v2_agent = agent


def agent(obs):
    try:
        idx = _v2_agent(obs)
    except Exception:
        idx = []
    sel = (obs or {}).get("select")
    if not sel:
        return []
    opts = sel.get("option") or []
    if not opts:
        return []
    lo = sel.get("minCount") or 0
    hi = min(sel.get("maxCount") or 0, len(opts))
    k = lo if lo > 0 else 1
    k = max(lo, min(k, hi))
    out, seen = [], set()
    for i in (idx or []):
        if isinstance(i, bool):
            continue
        try:
            i = int(i)
        except Exception:
            continue
        if 0 <= i < len(opts) and i not in seen:
            seen.add(i)
            out.append(i)
    for i in range(len(opts)):
        if len(out) >= k:
            break
        if i not in seen:
            seen.add(i)
            out.append(i)
    return out[:hi]
